import re

data = _items[0]["json"]
template = data.get("skills_tailoring_prompt_template")
skills = data["master_cv"].get("skills", [])

if not isinstance(template, str):
    raise ValueError("Skills prompt is missing.")
if not isinstance(skills, list):
    raise ValueError("master_cv.skills must be an array.")

normalized = []
inventory = []

for group in skills:
    label = group.get("label", "")
    raw = group.get("value", group.get("content", []))

    if isinstance(raw, str):
        values = [
            part.strip()
            for part in re.split(r"[,;|]", raw)
            if part.strip()
        ]
    elif isinstance(raw, list):
        values = [value.strip() for value in raw if isinstance(value, str) and value.strip()]
    else:
        values = []

    normalized.append({"label": label, "skills": values})
    inventory.extend(values)

compact = json.dumps(normalized, ensure_ascii=False, separators=(",", ":"))
prompt = template
prompt = prompt.replace("[[job_description]]", data["job_description"])
prompt = prompt.replace("[[original_skills_json]]", compact)
prompt = prompt.replace("[[skills_json]]", compact)

return [{
    "json": {
        **data,
        "skills_tailoring_prompt": prompt,
        "original_skill_inventory": inventory,
    }
}]

